#!/usr/bin/env node
/**
 * CI gate: catalog keys must stay readable.
 *
 * The catalog's keys were originally generated by slugging whole English
 * sentences, which produced names like
 * `contextMenu.mark.controlled.workspace.files.for` — long, unreadable, and
 * impossible to guess when editing copy.
 *
 * This gate blocks NEW keys that show the same degeneration. Rules are
 * calibrated against the real catalog: each one describes a defect rather than a
 * style preference, and together they cover ~4% of existing keys.
 *
 * Checks, per key:
 *  - longer than MAX_LENGTH characters
 *  - ends on a function word (the slug stopped mid-phrase)
 *  - contains a filename segment (codemod artefact, e.g. PageRenderertsx)
 *  - ends with a numeric suffix (auto-disambiguation leftover, `.2`)
 *  - contains a segment of more than MAX_SEGMENT_WORDS words
 *
 * Deliberately NOT checked: segment count. "contextMenu.get.this.revision" has
 * four segments and reads fine, while half the catalog exceeds three; a rule
 * half the catalog breaks is noise, not a standard.
 *
 * Usage: node scripts/validate-i18n-key-quality.mjs [--json]
 */
import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const JSON_OUT = process.argv.includes("--json");

const MAX_LENGTH = 56;
const MAX_SEGMENT_WORDS = 5;
const DANGLING =
  /\.(is|the|or|and|to|of|a|an|its|no|not|for|with|that|in|on|by|at)$/;
const FILENAME_SEGMENT = /tsx$|jsx$/i;
const NUMERIC_SUFFIX = /\.\d+$/;

/**
 * Keys that already violate the rules, accepted while the tail is ground down.
 * Shrink this list; it is a schedule, not a permission.
 */
const BASELINE = new Set([
  "browse.integration.records.content.inclusion.remains.unknown",
  "browse.integration.records.found.current.content.inclusion",
  "browse.loading.2",
  "browse.no",
  "browse.partial.2",
  "browse.refreshed.workspace.stream.views.remain.authoritative",
  "browse.risk.paths.up.to.100",
  "browse.run.preflight.2",
  "browse.search.list.2",
  "browse.the.backend.returned.a.repeated.2",
  "browse.zoom.in.2",
  "browse.zoom.out.2",
  "companySubmit.connection.changed.verification.is.required.again",
  "companySubmit.connection.identity.unavailable.real.launch",
  "companySubmit.simulation.running.submission.result.unverified",
  "companySubmit.simulation.session.or.submission.outcome.unknown",
  "contextMenu.copy.depot.path.2",
  "contextMenu.copy.depot.paths.2",
  "contextMenu.copy.names.2",
  "contextMenu.create.a.numbered.cl.and.2",
  "contextMenu.get.this.revision.2",
  "contextMenu.open.global.tab.2",
  "contextMenu.open.global.tab.3",
  "contextMenu.view.shelved.content.2",
  "files.add.2",
  "files.as.of.changelist.2",
  "files.as.of.date.2",
  "files.blocked.2",
  "files.conflict.block.s.2",
  "files.conflict.inspection.timed.out.after.30",
  "files.delete.2",
  "files.destination.default.pending.changelist.no.automatic",
  "files.file.revision.2",
  "files.files.2",
  "files.get.revision.2",
  "files.ignored.2",
  "files.latest.head.2",
  "files.loading.2",
  "files.no",
  "files.no.workspace.root.configured.select.2",
  "files.source.depot.2",
  "files.sync.scope.2",
  "files.target.local.2",
  "files.unknown.2",
  "files.untracked.2",
  "pending.changelist.creation.outcome.is.unconfirmed.refresh",
  "pending.connection.identity.changed.nothing.was.submitted",
  "pending.connection.settings.2",
  "pending.continue.search.up.to.10",
  "pending.create.2",
  "pending.discard.and.close.2",
  "pending.files.2",
  "pending.files.3",
  "pending.incomplete.2",
  "pending.new.changelist.2",
  "pending.new.changelist.3",
  "pending.new.cl.2",
  "pending.no.description.2",
  "pending.operation.2",
  "pending.operation.in.progress.2",
  "pending.pages.2",
  "pending.replacement.overwrites.selected.shelf.revisions.unselected",
  "pending.run.preflight.2",
  "pending.select.valid.streams.maximum.16",
  "pending.shelved.files.2",
  "pending.unknown.2",
  "pending.unknown.3",
  "pending.unknown.4",
  "pending.unknown.5",
  "pending.unknown.6",
  "pending.unknown.7",
  "pending.unmapped.2",
  "pending.user.2",
  "search.search.failed.2",
  "search.search.submitted.and.pending.changelists.workspace",
  "search.searching.2",
  "settings.checking.2",
  "settings.checking.3",
  "settings.connection.generation.changed.nothing.was.created",
  "settings.connection.name.must.contain.1.128",
  "settings.creating.2",
  "settings.dark.2",
  "settings.default.5.minutes.set.to.0",
  "settings.delete.all.logs.2",
  "settings.delete.this.saved.connection.2",
  "settings.global.preferences.saved.connections.switch.only",
  "settings.i.completed.external.authentication.check.status",
  "settings.light.2",
  "settings.logging.out.2",
  "settings.on",
  "settings.requires.windows.p4.server.2023.1",
  "settings.saved.connections.changed.concurrently.and.reload",
  "shell.cancelling.2",
  "shell.currently.visible.column.configuration.not.connected",
  "shell.execution.can.partially.succeed.cancellation.requests",
  "shell.folder.operations.include.all.descendants.recursively",
  "shell.insufficient.samples.5",
  "tools.new.unviewed.errors.2",
  "tools.retention.days.1.30",
  "tools.retention.must.be.1.30",
  "tools.to",
  "update.installing.update.2",
  "update.restarting.2",
  "update.the.update.package.failed.verification.2",
  "workspaces.connection.generation.changed.no.workspace.mutation",
  "workspaces.search.workspaces.2",
  "workspaces.the.active.connection.changed.refresh.workspaces",
  "workspaces.the.current.profile.requires.login.authenticate",
]);

const CATALOGS = [
  "src/shared/i18n/catalog.zh.ts",
  "src/shared/i18n/catalog.en.ts",
];

/** Catalog entries may wrap onto the next line; both quote styles occur. */
function keysIn(file) {
  const src = fs.readFileSync(path.join(ROOT, file), "utf8");
  return [...src.matchAll(/^ {2}"([^"]+)":/gm)].map((m) => m[1]);
}

function problems(key) {
  const found = [];
  if (key.length > MAX_LENGTH)
    found.push(`length ${key.length} > ${MAX_LENGTH}`);
  if (DANGLING.test(key)) found.push("ends on a function word");
  if (NUMERIC_SUFFIX.test(key)) found.push("numeric suffix");
  const segments = key.split(".");
  const fileSegment = segments.find(
    (s) => FILENAME_SEGMENT.test(s) && s.length > 6,
  );
  if (fileSegment) found.push(`filename segment "${fileSegment}"`);
  for (const s of segments) {
    const words = s.match(/[A-Z]?[a-z]+/g) ?? [];
    if (words.length > MAX_SEGMENT_WORDS)
      found.push(`segment "${s}" has ${words.length} words`);
  }
  return found;
}

const violations = [];
for (const file of CATALOGS) {
  for (const key of keysIn(file)) {
    const issues = problems(key);
    if (!issues.length) continue;
    const kind = BASELINE.has(key) ? "baseline" : "new";
    violations.push({ file, key, issues, kind });
  }
}

const fresh = violations.filter((v) => v.kind === "new");
const known = violations.length - fresh.length;

if (JSON_OUT) {
  const outPath = path.join(ROOT, "artifacts/l10n/key-quality.json");
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(
    outPath,
    JSON.stringify(
      { count: violations.length, fresh: fresh.length, violations },
      null,
      1,
    ),
  );
  console.log(
    `wrote ${outPath} (${violations.length} violations, ${fresh.length} new)`,
  );
  process.exit(fresh.length ? 1 : 0);
}

if (fresh.length) {
  console.error(
    `\n✗ ${fresh.length} new catalog key(s) violate the naming rules.\n` +
      `  Name keys <namespace>.<object>.<action>: readable, no sentence slugs,\n` +
      `  no filename segments, no numeric suffixes.\n`,
  );
  for (const v of fresh)
    console.error(`  ${v.key}\n      ${v.issues.join("; ")}`);
  process.exit(1);
}

console.log(
  known
    ? `✓ no new unreadable catalog keys (${known} known keys recorded in the baseline)`
    : "✓ all catalog keys satisfy the naming rules",
);
